package com.backend.nutri_predic.actividadfisica.controller;
import com.backend.nutri_predic.actividadfisica.dto.*; import com.backend.nutri_predic.actividadfisica.service.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/clientes/{clienteId}/evaluaciones-actividad-fisica") public class EvaluacionActividadFisicaController { private final EvaluacionActividadFisicaService service; public EvaluacionActividadFisicaController(EvaluacionActividadFisicaService service){this.service=service;} @PostMapping public EvaluacionActividadFisicaResponse registrar(@PathVariable Long clienteId,@Valid @RequestBody EvaluacionActividadFisicaRequest r,Authentication a){return service.registrar(clienteId,r,a);} @GetMapping public List<EvaluacionActividadFisicaResponse> listar(@PathVariable Long clienteId,Authentication a){return service.listar(clienteId,a);}}
